def _write_readme_epic_map(repo_root: Path, epic_ids: list[str]) -> None: rows = '\n'.join((f'| [{epic_id}](docs/project/{epic_id}.sample.md) | Sample |' for epic_id in epic_ids)); (repo_root / 'README.md').write_text(f'# Sample\n\n## EPIC Map\n\n| EPIC | Scope |\n|---|---|\n{rows}\n', encoding='utf-8')
def _project_epic_ids(repo_root: Path) -> list[str]: project = repo_root / 'docs' / 'project'; return sorted((path.name.split('.', 1)[0] for path in project.glob('EPIC-*.md')))
def _write_epic(repo_root: Path, epic_id: str, *, kind: str | None=None, residual: bool=False, update_readme: bool=True) -> None: project = repo_root / 'docs' / 'project'; project.mkdir(parents=True, exist_ok=True); file_marker = f'<!-- epic-file: {kind} -->\n' if kind else ''; residue_marker = '<!-- epic-owned: horizontal -->\n' if residual else ''; (project / f'{epic_id}.sample.md').write_text(f'# {epic_id}: Sample\n{file_marker}{residue_marker}\n- **AC8.13.68**: E2E EPIC traceability.\n', encoding='utf-8'); _write_readme_epic_map(repo_root, _project_epic_ids(repo_root)) if update_readme else None
def _write_test(repo_root: Path, rel_path: str, content: str) -> None: path = repo_root / rel_path; path.parent.mkdir(parents=True, exist_ok=True); path.write_text(content.strip() + '\n', encoding='utf-8')
