def test_discover_e2e_assets_prunes_excluded_directories(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:
    valid_e2e = tmp_path / 'tests' / 'e2e' / 'test_valid.py'; valid_e2e.parent.mkdir(parents=True, exist_ok=True); valid_e2e.write_text('def test_valid(): pass\n', encoding='utf-8'); excluded_node = tmp_path / 'node_modules' / 'e2e' / 'test_ignored.py'; excluded_node.parent.mkdir(parents=True, exist_ok=True); excluded_node.write_text('def test_ignored(): pass\n', encoding='utf-8'); excluded_next = tmp_path / '.next' / 'e2e' / 'test_next.py'; excluded_next.parent.mkdir(parents=True, exist_ok=True); excluded_next.write_text('def test_next(): pass\n', encoding='utf-8'); visited_roots: list[str] = []; real_walk = checker.os.walk
    def spied_walk(top: Path | str, *args: Any, **kwargs: Any):
        for (root, dirs, files) in real_walk(top, *args, **kwargs): visited_roots.append(Path(root).name); yield (root, dirs, files)
    monkeypatch.setattr(checker.os, 'walk', spied_walk); assets = checker.discover_e2e_assets(tmp_path); assert assets == ['tests/e2e/test_valid.py']; assert 'node_modules' not in visited_roots; assert '.next' not in visited_roots
